function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function get(path){const r=await fetch(origin()+path,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('AlphaLab API '+r.status+': '+await r.text());return r.json()}
async function run(input){const profile=input.profile==='runtime'?'runtime':'demo',backtestLimit=Math.max(1,Math.min(20,Number(input.backtest_limit||5))),symbolLimit=Math.max(1,Math.min(100,Number(input.symbol_limit||30)));const [providers,dataTools,symbolCatalog,projects,components,backtests]=await Promise.all([get('/api/data/providers'),get('/api/agent/data-tools'),get('/api/data/market/symbols?profile='+profile),get('/api/pipeline/projects'),get('/api/pipeline/components'),get('/api/backtests?limit='+backtestLimit)]);const symbols=Array.isArray(symbolCatalog.symbols)?symbolCatalog.symbols:[];return{profile,providers,dataTools,fundamentalFields:['shares','market_cap','ep','bp','roe','gross_margin','leverage','profit_growth','revenue_growth'],riskFactorNames:['MKT','SMB','HML','MOM','RMW','rf'],symbols:symbols.slice(0,symbolLimit),symbolCount:symbols.length,pipelineStages:['selection','portfolio','execution'],projects,components,backtests,observedAt:new Date().toISOString()}}
